{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C11", "C28", "C36", "C42", "C23", "C26", "C07", "C55", "C68", "C74"],
  "contradictory_card_ids": ["C25", "C09"],
  "prediction_basis_card_ids": ["C11", "C28", "C36", "C42", "C23", "C26", "C07", "C55"],
  "claims": [
    {
      "claim": "Omadacycline, a structurally related tetracycline, has measured oral bioavailability of 34.5% in healthy adults after a 300 mg fasted oral dose, with 300 mg oral bioequivalent to 100 mg IV.",
      "card_ids": ["C11", "C28", "C36", "C42"]
    },
    {
      "claim": "Tetracycline, the parent scaffold, has reported human oral bioavailability of 75%, >70%, and 80–90%.",
      "card_ids": ["C23", "C26", "C07"]
    },
    {
      "claim": "L3 oral exposure for tetracycline shows substantial systemic exposure after oral dosing (AUC0-inf 67.4 µg·h/mL after 500 mg), consistent with meaningful oral absorption.",
      "card_ids": ["C55"]
    },
    {
      "claim": "L4 records for tetracycline show favorable dissolution/salt formation and no impairment of intestinal absorption in a rat anaphylaxis model, providing limited supportive context for the absorption component of the tetracycline class.",
      "card_ids": ["C68", "C74", "C75"]
    },
    {
      "claim": "The 0.5% F omadacycline record is formulation-specific (slow dissolution tablet) and does not overturn the 34.5% F value; generic low-bioavailability statements for tetracyclines are contradicted by quantitative records.",
      "card_ids": ["C25", "C09"]
    },
    {
      "claim": "Low-F records for loperamide, butorphanol, ganciclovir, sulpiride, levosulpiride, DHE, DA-8010, and DHEC are structurally unrelated to the tetracycline query and do not provide transferable evidence for F <20%.",
      "card_ids": ["C02", "C15", "C33", "C10", "C17", "C31", "C35", "C04", "C03", "C27", "C08", "C13", "C18", "C29", "C58", "C60", "C63", "C66"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C68", "C74"]
    },
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C75"]
    },
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C67", "C69", "C70", "C71", "C72", "C73", "C76", "C77", "C78"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability or permeability record for the query molecule itself.",
    "Structural differences between the query (7-fluoro, 9-pyrrolidinoacetamido) and omadacycline/tetracycline may alter absorption, efflux, and first-pass; transfer is inferred, not measured.",
    "No formulation, dose, or prandial condition is specified for the query.",
    "L4 records are mostly for other scaffolds (nintedanib, doxorubicin, BRACO19, linezolid, ciprofloxacin) and do not directly inform the query endpoint.",
    "No measured gut-wall efflux or intestinal metabolism data for the query are available at this level."
  ],
  "decision_summary": "Predicted high because the most transferable experimental contexts are tetracycline-class molecules with F >=20% (omadacycline 34.5%; tetracycline 75%), and L3/L4 records for tetracycline are consistent with meaningful oral absorption and favorable dissolution. The physicochemical low-F prior and formulation-specific low records are acknowledged but do not constitute affirmative threshold-relevant evidence for F <20%; unresolved uncertainty is reflected in moderate confidence and evidence gaps."
}

